CREATE TABLE IF NOT EXISTS fiado (id INTEGER PRIMARY KEY AUTOINCREMENT,branch_id TEXT NOT NULL DEFAULT 'acailandia',order_id TEXT NOT NULL,customer_name TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',amount_cents INTEGER NOT NULL DEFAULT 0,paid_cents INTEGER NOT NULL DEFAULT 0,original_total_cents INTEGER NOT NULL DEFAULT 0,original_method TEXT NOT NULL DEFAULT 'dinheiro',status TEXT NOT NULL DEFAULT 'aberto',notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,paid_at TEXT);
ALTER TABLE cash_register_sessions ADD COLUMN fiado_cents INTEGER NOT NULL DEFAULT 0;
